def verify(solution):
    n = len(solution)
    for i in range(n):
        for j in range(i+1, n):
            if solution[i] == solution[j]:
                return False, f"Same column at rows {i},{j}"
            if abs(solution[i] - solution[j]) == abs(i - j):
                return False, f"Same diagonal at rows {i},{j}"
    return True, "Valid"

print(verify([0, 2, 4, 1, 3, 8, 10, 14, 20, 17, 19, 16, 18, 6, 11, 9, 7, 5, 13, 15, 12]))
